1	/*
2	 * GroupNorm + SiLU AscendC kernel
3	 * Input: x[N, C, H, W], gamma[C], beta[C]
4	 * Output: y[N, C, H, W]
5	 *
6	 * For each group:
7	 *   1. Compute mean over (channels_per_group, H, W)
8	 *   2. Compute variance over (channels_per_group, H, W)
9	 *   3. Normalize: (x - mean) / sqrt(var + eps)
10	 *   4. Apply gamma, beta
11	 *   5. If activate_silu: SiLU(x) = x * sigmoid(x)
12	 */
13	#include "kernel_operator.h"
14	
15	using namespace AscendC;
16	
17	class KernelGroupNormSilu {
18	public:
19	    __aicore__ inline KernelGroupNormSilu() {}
20	
21	    __aicore__ inline void Init(
22	        GM_ADDR x, GM_ADDR gamma, GM_ADDR beta, GM_ADDR y,
23	        int64_t N, int64_t C, int64_t H, int64_t W,
24	        int64_t numGroups, int64_t channelsPerGroup, int64_t spatialSize,
25	        int64_t totalGroups, int64_t usedCoreNum, int64_t tasksPerCore,
26	        int64_t activateSilu, float eps, int64_t dtypeSize) {
27	
28	        N_ = N;
29	        C_ = C;
30	        H_ = H;
31	        W_ = W;
32	        numGroups_ = numGroups;
33	        channelsPerGroup_ = channelsPerGroup;
34	        spatialSize_ = spatialSize;
35	        totalGroups_ = totalGroups;
36	        usedCoreNum_ = usedCoreNum;
37	        tasksPerCore_ = tasksPerCore;
38	        activateSilu_ = activateSilu;
39	        eps_ = eps;
40	        dtypeSize_ = dtypeSize;
41	
42	        if (dtypeSize == 4) {
43	            // float32
44	            xGmFp32_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(x), N * C * H * W);
45	            gammaGmFp32_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(gamma), C);
46	            betaGmFp32_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(beta), C);
47	            yGmFp32_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(y), N * C * H * W);
48	        } else {
49	            // float16
50	            xGmFp16_.SetGlobalBuffer(reinterpret_cast<__gm__ half*>(x), N * C * H * W);
51	            gammaGmFp16_.SetGlobalBuffer(reinterpret_cast<__gm__ half*>(gamma), C);
52	            betaGmFp16_.SetGlobalBuffer(reinterpret_cast<__gm__ half*>(beta), C);
53	            yGmFp16_.SetGlobalBuffer(reinterpret_cast<__gm__ half*>(y), N * C * H * W);
54	        }
55	    }
56	
57	    __aicore__ inline void Process() {
58	        int64_t coreIdx = GetBlockIdx();
59	        if (coreIdx >= usedCoreNum_) {
60	            return;
61	        }
62	
63	        for (int64_t localIdx = 0; localIdx < tasksPerCore_; localIdx++) {
64	            int64_t groupIdx = coreIdx * tasksPerCore_ + localIdx;
65	            if (groupIdx >= totalGroups_) {
66	                break;
67	            }
68	
69	            int64_t n = groupIdx / numGroups_;
70	            int64_t g = groupIdx % numGroups_;
71	
72	            // Compute mean and variance for this group
73	            float mean, variance, rstd;
74	            if (dtypeSize_ == 4) {
75	                mean = ComputeMeanFp32(n, g);
76	                variance = ComputeVarianceFp32(n, g, mean);
77	            } else {
78	                mean = ComputeMeanFp16(n, g);
79	                variance = ComputeVarianceFp16(n, g, mean);
80	            }
81	            rstd = ComputeRstd(variance);
82	
83	            // Normalize, apply gamma/beta, SiLU, write back
84	            for (int64_t cOffset = 0; cOffset < channelsPerGroup_; cOffset++) {
85	                int64_t c = g * channelsPerGroup_ + cOffset;
86	                int64_t baseOffset = ((n * C_) + c) * spatialSize_;
87	
88	                float gammaF, betaF;
89	                if (dtypeSize_ == 4) {
90	                    gammaF = gammaGmFp32_.GetValue(c);
91	                    betaF = betaGmFp32_.GetValue(c);
92	                } else {
93	                    gammaF = static_cast<float>(gammaGmFp16_.GetValue(c));
94	                    betaF = static_cast<float>(betaGmFp16_.GetValue(c));
95	                }
96	
97	                for (int64_t hw = 0; hw < spatialSize_; hw++) {
98	                    float xF;
99	                    if (dtypeSize_ == 4) {
100	                        xF = xGmFp32_.GetValue(baseOffset + hw);
101	                    } else {
102	                        xF = static_cast<float>(xGmFp16_.GetValue(baseOffset + hw));
103	                    }
104	
105	                    // Normalize
106	                    float normalized = (xF - mean) * rstd;
107	
108	                    // Apply gamma and beta
109	                    float shifted = normalized * gammaF + betaF;
110	
111	                    // Optional SiLU
112	                    float result;
113	                    if (activateSilu_ != 0) {
114	                        float sigmoidVal = SigmoidApprox(shifted);
115	                        result = shifted * sigmoidVal;
116	                    } else {
117	                        result = shifted;
118	                    }
119	
120	                    // Write back
121	                    if (dtypeSize_ == 4) {
122	                        yGmFp32_.SetValue(baseOffset + hw, result);
123	                    } else {
124	                        yGmFp16_.SetValue(baseOffset + hw, static_cast<half>(result));
125	                    }
126	                }
127	            }
128	        }
129	    }
130	
131	private:
132	    __aicore__ inline float ComputeMeanFp32(int64_t n, int64_t g) {
133	        float groupSum = 0.0f;
134	        for (int64_t cOffset = 0; cOffset < channelsPerGroup_; cOffset++) {
135	            int64_t c = g * channelsPerGroup_ + cOffset;
136	            int64_t baseOffset = ((n * C_) + c) * spatialSize_;
137	            for (int64_t hw = 0; hw < spatialSize_; hw++) {
138	                groupSum += xGmFp32_.GetValue(baseOffset + hw);
139	            }
140	        }
141	        float groupCount = static_cast<float>(channelsPerGroup_ * spatialSize_);
142	        return groupSum / groupCount;
143	    }
144	
145	    __aicore__ inline float ComputeMeanFp16(int64_t n, int64_t g) {
146	        float groupSum = 0.0f;
147	        for (int64_t cOffset = 0; cOffset < channelsPerGroup_; cOffset++) {
148	            int64_t c = g * channelsPerGroup_ + cOffset;
149	            int64_t baseOffset = ((n * C_) + c) * spatialSize_;
150	            for (int64_t hw = 0; hw < spatialSize_; hw++) {
151	                groupSum += static_cast<float>(xGmFp16_.GetValue(baseOffset + hw));
152	            }
153	        }
154	        float groupCount = static_cast<float>(channelsPerGroup_ * spatialSize_);
155	        return groupSum / groupCount;
156	    }
157	
158	    __aicore__ inline float ComputeVarianceFp32(int64_t n, int64_t g, float mean) {
159	        float groupSqDiffSum = 0.0f;
160	        for (int64_t cOffset = 0; cOffset < channelsPerGroup_; cOffset++) {
161	            int64_t c = g * channelsPerGroup_ + cOffset;
162	            int64_t baseOffset = ((n * C_) + c) * spatialSize_;
163	            for (int64_t hw = 0; hw < spatialSize_; hw++) {
164	                float diff = xGmFp32_.GetValue(baseOffset + hw) - mean;
165	                groupSqDiffSum += diff * diff;
166	            }
167	        }
168	        float groupCount = static_cast<float>(channelsPerGroup_ * spatialSize_);
169	        return groupSqDiffSum / groupCount;
170	    }
171	
172	    __aicore__ inline float ComputeVarianceFp16(int64_t n, int64_t g, float mean) {
173	        float groupSqDiffSum = 0.0f;
174	        for (int64_t cOffset = 0; cOffset < channelsPerGroup_; cOffset++) {
175	            int64_t c = g * channelsPerGroup_ + cOffset;
176	            int64_t baseOffset = ((n * C_) + c) * spatialSize_;
177	            for (int64_t hw = 0; hw < spatialSize_; hw++) {
178	                float diff = static_cast<float>(xGmFp16_.GetValue(baseOffset + hw)) - mean;
179	                groupSqDiffSum += diff * diff;
180	            }
181	        }
182	        float groupCount = static_cast<float>(channelsPerGroup_ * spatialSize_);
183	        return groupSqDiffSum / groupCount;
184	    }
185	
186	    __aicore__ inline float ComputeRstd(float variance) {
187	        float varEps = variance + eps_;
188	        float sqrtVal = SqrtApprox(varEps);
189	        return 1.0f / sqrtVal;
190	    }
191	
192	    __aicore__ inline float SqrtApprox(float x) {
193	        if (x <= 0.0f) return 0.0f;
194	        float guess = x;
195	        if (x > 1.0f) {
196	            guess = x * 0.5f;
197	        } else {
198	            guess = 1.0f;
199	        }
200	        for (int i = 0; i < 6; i++) {
201	            guess = 0.5f * (guess + x / guess);
202	        }
203	        return guess;
204	    }
205	
206	    __aicore__ inline float SigmoidApprox(float x) {
207	        // Piecewise sigmoid approximation
208	        if (x >= 0.0f) {
209	            float expNegX = ExpApprox(-x);
210	            return 1.0f / (1.0f + expNegX);
211	        } else {
212	            float expX = ExpApprox(x);
213	            return expX / (1.0f + expX);
214	        }
215	    }
216	
217	    __aicore__ inline float ExpApprox(float x) {
218	        // Taylor series for exp(x)
219	        float result = 1.0f;
220	        float term = 1.0f;
221	        for (int i = 1; i <= 10; i++) {
222	            term *= x / static_cast<float>(i);
223	            result += term;
224	        }
225	        return result;
226	    }
227	
228	private:
229	    GlobalTensor<float> xGmFp32_;
230	    GlobalTensor<float> gammaGmFp32_;
231	    GlobalTensor<float> betaGmFp32_;
232	    GlobalTensor<float> yGmFp32_;
233	
234	    GlobalTensor<half> xGmFp16_;
235	    GlobalTensor<half> gammaGmFp16_;
236	    GlobalTensor<half> betaGmFp16_;
237	    GlobalTensor<half> yGmFp16_;
238	
239	    int64_t N_, C_, H_, W_;
240	    int64_t numGroups_, channelsPerGroup_, spatialSize_;
241	    int64_t totalGroups_, usedCoreNum_, tasksPerCore_;
242	    int64_t activateSilu_;
243	    float eps_;
244	    int64_t dtypeSize_;
245	};
246	
247	extern "C" __global__ __aicore__ void group_norm_silu(
248	    GM_ADDR x, GM_ADDR gamma, GM_ADDR beta, GM_ADDR y,
249	    int64_t N, int64_t C, int64_t H, int64_t W,
250	    int64_t numGroups, int64_t channelsPerGroup, int64_t spatialSize,
251	    int64_t totalGroups, int64_t usedCoreNum, int64_t tasksPerCore,
252	    int64_t activateSilu, float eps, int64_t dtypeSize) {
253	
254	    KernelGroupNormSilu op;
255	    op.Init(x, gamma, beta, y, N, C, H, W, numGroups, channelsPerGroup, spatialSize,
256	            totalGroups, usedCoreNum, tasksPerCore, activateSilu, eps, dtypeSize);
257	    op.Process();
258	}
