7	#include "kernels/aclrtlaunch_group_norm_silu.h"
8	
9	namespace ascend_kernel {
10	
11	at::Tensor group_norm_silu(
12	    const at::Tensor& x,
13	    const at::Tensor& gamma,
14	    const at::Tensor& beta,
15	    int64_t num_groups,
16	    double eps,
17	    int64_t activate_silu) {
18	
19	    // Input validation
20	    TORCH_CHECK(x.dim() >= 2, "Input x must have at least 2 dimensions");
21	    TORCH_CHECK(x.size(1) == gamma.size(0), "Channel mismatch between x and gamma");
22	    TORCH_CHECK(x.size(1) == beta.size(0), "Channel mismatch between x and beta");
23	    TORCH_CHECK(x.size(1) % num_groups == 0, "num_channels must be divisible by num_groups");
24	    TORCH_CHECK(x.dtype() == at::kHalf || x.dtype() == at::kFloat, "Only float16 and float32 are supported");
25	    TORCH_CHECK(gamma.dtype() == x.dtype(), "gamma must have same dtype as x");
26	    TORCH_CHECK(beta.dtype() == x.dtype(), "beta must have same dtype as x");
27	    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
28	
29	    // Create output tensor
30	    auto y = at::empty_like(x);
31	
32	    // Get shape info
33	    int64_t N = x.size(0);
34	    int64_t C = x.size(1);
35	    int64_t H = (x.dim() > 2) ? x.size(2) : 1;
36	    int64_t W = (x.dim() > 3) ? x.size(3) : 1;
37	    int64_t channelsPerGroup = C / num_groups;
38	    int64_t spatialSize = H * W;
39	    int64_t totalGroups = N * num_groups;
