#include "kernels/aclrtlaunch_group_norm_silu.h"

namespace ascend_kernel {

at::Tensor group_norm_silu(
    const at::Tensor& x,
    const at::Tensor& gamma,
    const at::Tensor& beta,
    int64_t num_groups,
    double eps,
    int64_t activate_silu) {

    // Input validation
    TORCH_CHECK(x.dim() >= 2, "Input x must have at least 2 dimensions");
    TORCH_CHECK(x.size(1) == gamma.size(0), "Channel mismatch between x and gamma");
    TORCH_CHECK(x.size(1) == beta.size(0), "Channel mismatch between x and beta");
    TORCH_CHECK(x.size(1) % num_groups == 0, "num_channels must be divisible by num_groups");
    TORCH_CHECK(x.dtype() == at::kHalf || x.dtype() == at::kFloat, "Only float16 and float32 are supported");
    TORCH_CHECK(gamma.dtype() == x.dtype(), "gamma must have same dtype as x");
    TORCH_CHECK(beta.dtype() == x.dtype(), "beta must have same dtype as x");
    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");

    // Create output tensor
    auto y = at::empty_like(x);

    // Get shape info
    int64_t N = x.size(0);
    int64_t C = x.size(1);
    int64_t H = (x.dim() > 2) ? x.size(2) : 1;
    int64_t W = (x.dim() > 3) ? x.size(3) : 1;
    int64_t channelsPerGroup = C / num_groups;
    int64_t spatialSize = H * W;
    int64_t totalGroups = N * num_groups;

    // Get platform info
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    int64_t usedCoreNum = std::min(coreNum, totalGroups);
    int64_t tasksPerCore = (totalGroups + usedCoreNum - 1) / usedCoreNum;

    // All parameters must be left values for EXEC_KERNEL_CMD
    float epsF = static_cast<float>(eps);
    int64_t activateSiluInt = activate_silu;
    int64_t dtypeSize = (x.dtype() == at::kFloat) ? 4 : 2;

    // Launch kernel
    int64_t blockDim = usedCoreNum;

    EXEC_KERNEL_CMD(group_norm_silu, blockDim,
        x, gamma, beta, y,
        N, C, H, W,
        num_groups, channelsPerGroup, spatialSize, totalGroups,
        usedCoreNum, tasksPerCore, activateSiluInt, epsF, dtypeSize);

    return y;
}

} // namespace ascend_kernel

