1	#include "torch_kernel_helper.h"
2	#include "tiling/platform/platform_ascendc.h"
3	#include <torch/extension.h>
4	#include <cmath>
5	
6	// Include auto-generated kernel launch header
7	#include "kernels/aclrtlaunch_group_norm_silu.h"
8	
9	namespace ascend_kernel {
10	
11	at::Tensor group_norm_silu(
12	    const at::Tensor& x,
13	    const at::Tensor& gamma,
14	    const at::Tensor& beta,
15	    int64_t num_groups,
16	    double eps,
17	    int64_t activate_silu) {
18	
19	    // Input validation
20	    TORCH_CHECK(x.dim() >= 2, "Input x must have at least 2 dimensions");
21	    TORCH_CHECK(x.size(1) == gamma.size(0), "Channel mismatch between x and gamma");
22	    TORCH_CHECK(x.size(1) == beta.size(0), "Channel mismatch between x and beta");
23	    TORCH_CHECK(x.size(1) % num_groups == 0, "num_channels must be divisible by num_groups");
24	    TORCH_CHECK(x.dtype() == at::kHalf || x.dtype() == at::kFloat, "Only float16 and float32 are supported");
25	    TORCH_CHECK(gamma.dtype() == x.dtype(), "gamma must have same dtype as x");
26	    TORCH_CHECK(beta.dtype() == x.dtype(), "beta must have same dtype as x");
27	    TORCH_CHECK(x.is_contiguous(), "x must be contiguous");
28	
29	    // Create output tensor
30	    auto y = at::empty_like(x);
31	
32	    // Get shape info
33	    int64_t N = x.size(0);
34	    int64_t C = x.size(1);
35	    int64_t H = (x.dim() > 2) ? x.size(2) : 1;
36	    int64_t W = (x.dim() > 3) ? x.size(3) : 1;
37	    int64_t channelsPerGroup = C / num_groups;
38	    int64_t spatialSize = H * W;
39	    int64_t totalGroups = N * num_groups;
40	
41	    // Get platform info
42	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
43	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
44	    int64_t usedCoreNum = std::min(coreNum, totalGroups);
45	    int64_t tasksPerCore = (totalGroups + usedCoreNum - 1) / usedCoreNum;
46	
47	    // All parameters must be left values for EXEC_KERNEL_CMD
48	    float epsF = static_cast<float>(eps);
49	    int32_t activateSiluInt = static_cast<int32_t>(activate_silu);
50	    int32_t dtypeSize = (x.dtype() == at::kFloat) ? 4 : 2;
51	
52	    // Launch kernel
53	    int32_t blockDim = static_cast<int32_t>(usedCoreNum);
54	
55	    EXEC_KERNEL_CMD(group_norm_silu, blockDim,
56	        x, gamma, beta, y,
57	        static_cast<int32_t>(N), static_cast<int32_t>(C), static_cast<int32_t>(H), static_cast<int32_t>(W),
58	        static_cast<int32_t>(num_groups), static_cast<int32_t>(channelsPerGroup), static_cast<int32_t>(spatialSize), static_cast<int32_t>(totalGroups),
59	        static_cast<int32_t>(usedCoreNum), static_cast<int32_t>(tasksPerCore), activateSiluInt, epsF, dtypeSize);
60	
61	    return y;
62	}
63	
64	} // namespace ascend_kernel
