1	/*
2	 * GroupNorm + SiLU AscendC kernel
3	 * Input: x[N, C, H, W], gamma[C], beta[C]
4	 * Output: y[N, C, H, W]
5	 *
6	 * For each group:
7	 *   1. Compute mean over (channels_per_group, H, W)
8	 *   2. Compute variance over (channels_per_group, H, W)
9	 *   3. Normalize: (x - mean) / sqrt(var + eps)
10	 *   4. Apply gamma, beta
11	 *   5. If activate_silu: SiLU(x) = x * sigmoid(x)
12	 */
13	#include "kernel_operator.h"
14	
15	using namespace AscendC;
16	
17	class KernelGroupNormSilu {
18	public:
19	    __aicore__ inline KernelGroupNormSilu() {}
20	
21	    __aicore__ inline void Init(
22	        GM_ADDR x, GM_ADDR gamma, GM_ADDR beta, GM_ADDR y,
23	        int32_t N, int32_t C, int32_t H, int32_t W,
24	        int32_t numGroups, int32_t channelsPerGroup, int32_t spatialSize,
25	        int32_t totalGroups, int32_t usedCoreNum, int32_t tasksPerCore,
26	        int32_t activateSilu, float eps, int32_t dtypeSize) {
27	
28	        N_ = N;
29	        C_ = C;
30	        H_ = H;
31	        W_ = W;
32	        numGroups_ = numGroups;
33	        channelsPerGroup_ = channelsPerGroup;
34	        spatialSize_ = spatialSize;
35	        totalGroups_ = totalGroups;
36	        usedCoreNum_ = usedCoreNum;
37	        tasksPerCore_ = tasksPerCore;
38	        activateSilu_ = activateSilu;
39	        eps_ = eps;
40	        dtypeSize_ = dtypeSize;
41	
42	        if (dtypeSize == 4) {
43	            // float32
44	            xGmFp32_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(x), N * C * H * W);
45	            gammaGmFp32_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(gamma), C);
46	            betaGmFp32_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(beta), C);
47	            yGmFp32_.SetGlobalBuffer(reinterpret_cast<__gm__ float*>(y), N * C * H * W);
48	        } else {
49	            // float16
50	            xGmFp16_.SetGlobalBuffer(reinterpret_cast<__gm__ half*>(x), N * C * H * W);
51	            gammaGmFp16_.SetGlobalBuffer(reinterpret_cast<__gm__ half*>(gamma), C);
52	            betaGmFp16_.SetGlobalBuffer(reinterpret_cast<__gm__ half*>(beta), C);
53	            yGmFp16_.SetGlobalBuffer(reinterpret_cast<__gm__ half*>(y), N * C * H * W);
54	        }
55	    }
56	
57	    __aicore__ inline void Process() {
58	        int32_t coreIdx = GetBlockIdx();
59	        if (coreIdx >= usedCoreNum_) {
60	            return;
61	        }
62	
63	        for (int32_t localIdx = 0; localIdx < tasksPerCore_; localIdx++) {
64	            int32_t groupIdx = coreIdx * tasksPerCore_ + localIdx;
65	            if (groupIdx >= totalGroups_) {
66	                break;
67	            }
68	
69	            int32_t n = groupIdx / numGroups_;
70	            int32_t g = groupIdx % numGroups_;
71	
72	            // Compute mean and variance for this group
73	            float mean, variance, rstd;
74	            if (dtypeSize_ == 4) {
75	                mean = ComputeMeanFp32(n, g);
76	                variance = ComputeVarianceFp32(n, g, mean);
77	            } else {
78	                mean = ComputeMeanFp16(n, g);
79	                variance = ComputeVarianceFp16(n, g, mean);
80	            }
81	            rstd = ComputeRstd(variance);
82	
83	            // Normalize, apply gamma/beta, SiLU, write back
84	            for (int32_t cOffset = 0; cOffset < channelsPerGroup_; cOffset++) {
85	                int32_t c = g * channelsPerGroup_ + cOffset;
86	                int32_t baseOffset = ((n * C_) + c) * spatialSize_;
87	
88	                float gammaF, betaF;
89	                if (dtypeSize_ == 4) {
90	                    gammaF = gammaGmFp32_.GetValue(c);
91	                    betaF = betaGmFp32_.GetValue(c);
92	                } else {
93	                    gammaF = static_cast<float>(gammaGmFp16_.GetValue(c));
94	                    betaF = static_cast<float>(betaGmFp16_.GetValue(c));
95	                }
96	
97	                for (int32_t hw = 0; hw < spatialSize_; hw++) {
98	                    float xF;
99	                    if (dtypeSize_ == 4) {
100	                        xF = xGmFp32_.GetValue(baseOffset + hw);
101	                    } else {
102	                        xF = static_cast<float>(xGmFp16_.GetValue(baseOffset + hw));
103	                    }
104	
105	                    // Normalize
106	                    float normalized = (xF - mean) * rstd;
107	
108	                    // Apply gamma and beta
109	                    float shifted = normalized * gammaF + betaF;
110	
111	                    // Optional SiLU
112	                    float result;
113	                    if (activateSilu_ != 0) {
114	                        float sigmoidVal = SigmoidApprox(shifted);
115	                        result = shifted * sigmoidVal;
116	                    } else {
117	                        result = shifted;
118	                    }
119	
120	                    // Write back
121	                    if (dtypeSize_ == 4) {
122	                        yGmFp32_.SetValue(baseOffset + hw, result);
123	                    } else {
124	                        yGmFp16_.SetValue(baseOffset + hw, static_cast<half>(result));
125	                    }
126	                }
127	            }
128	        }
129	    }
130	
131	private:
132	    __aicore__ inline float ComputeMeanFp32(int32_t n, int32_t g) {
133	        float groupSum = 0.0f;
134	        for (int32_t cOffset = 0; cOffset < channelsPerGroup_; cOffset++) {
135	            int32_t c = g * channelsPerGroup_ + cOffset;
136	            int32_t baseOffset = ((n * C_) + c) * spatialSize_;
137	            for (int32_t hw = 0; hw < spatialSize_; hw++) {
138	                groupSum += xGmFp32_.GetValue(baseOffset + hw);
139	            }
140	        }
141	        float groupCount = static_cast<float>(channelsPerGroup_ * spatialSize_);
142	        return groupSum / groupCount;
143	    }
144	
145	    __aicore__ inline float ComputeMeanFp16(int32_t n, int32_t g) {
146	        float groupSum = 0.0f;
147	        for (int32_t cOffset = 0; cOffset < channelsPerGroup_; cOffset++) {
148	            int32_t c = g * channelsPerGroup_ + cOffset;
149	            int32_t baseOffset = ((n * C_) + c) * spatialSize_;
150	            for (int32_t hw = 0; hw < spatialSize_; hw++) {
151	                groupSum += static_cast<float>(xGmFp16_.GetValue(baseOffset + hw));
152	            }
153	        }
154	        float groupCount = static_cast<float>(channelsPerGroup_ * spatialSize_);
155	        return groupSum / groupCount;
156	    }
157	
158	    __aicore__ inline float ComputeVarianceFp32(int32_t n, int32_t g, float mean) {
159	        float groupSqDiffSum = 0.0f;
160	        for (int32_t cOffset = 0; cOffset < channelsPerGroup_; cOffset++) {
161	            int32_t c = g * channelsPerGroup_ + cOffset;
162	            int32_t baseOffset = ((n * C_) + c) * spatialSize_;
163	            for (int32_t hw = 0; hw < spatialSize_; hw++) {
164	                float diff = xGmFp32_.GetValue(baseOffset + hw) - mean;
165	                groupSqDiffSum += diff * diff;
166	            }
167	        }
168	        float groupCount = static_cast<float>(channelsPerGroup_ * spatialSize_);
169	        return groupSqDiffSum / groupCount;
170	    }
171	
172	    __aicore__ inline float ComputeVarianceFp16(int32_t n, int32_t g, float mean) {
173	        float groupSqDiffSum = 0.0f;
174	        for (int32_t cOffset = 0; cOffset < channelsPerGroup_; cOffset++) {
175	            int32_t c = g * channelsPerGroup_ + cOffset;
176	            int32_t baseOffset = ((n * C_) + c) * spatialSize_;
177	            for (int32_t hw = 0; hw < spatialSize_; hw++) {
178	                float diff = static_cast<float>(xGmFp16_.GetValue(baseOffset + hw)) - mean;
179	                groupSqDiffSum += diff * diff;
180	            }
181	        }
182	        float groupCount = static_cast<float>(channelsPerGroup_ * spatialSize_);
183	        return groupSqDiffSum / groupCount;
184	    }
185	
186	    __aicore__ inline float ComputeRstd(float variance) {
187	        float varEps = variance + eps_;
188	        float sqrtVal = SqrtApprox(varEps);
189	        return 1.0f / sqrtVal;
190	    }
191	
192	    __aicore__ inline float SqrtApprox(float x) {
193	        if (x <= 0.0f) return 0.0f;
194	        // Better initial guess using bit-hack approximation
195	        float guess = x;
196	        if (x > 1.0f) {
197	            guess = x * 0.5f;
198	        } else if (x > 0.01f) {
199	            guess = x * 2.0f + 0.3f;
200	        } else {
201	            guess = x * 10.0f + 0.05f;
202	        }
203	        for (int i = 0; i < 10; i++) {
204	            guess = 0.5f * (guess + x / guess);
205	        }
206	        return guess;
207	    }
208	
209	    __aicore__ inline float SigmoidApprox(float x) {
210	        // Piecewise sigmoid approximation
211	        if (x >= 0.0f) {
212	            float expNegX = ExpApprox(-x);
213	            return 1.0f / (1.0f + expNegX);
214	        } else {
215	            float expX = ExpApprox(x);
216	            return expX / (1.0f + expX);
217	        }
218	    }
219	
220	    __aicore__ inline float ExpApprox(float x) {
221	        // Taylor series for exp(x)
222	        float result = 1.0f;
223	        float term = 1.0f;
224	        for (int i = 1; i <= 10; i++) {
225	            term *= x / static_cast<float>(i);
226	            result += term;
227	        }
228	        return result;
229	    }
230	
231	private:
232	    GlobalTensor<float> xGmFp32_;
233	    GlobalTensor<float> gammaGmFp32_;
234	    GlobalTensor<float> betaGmFp32_;
235	    GlobalTensor<float> yGmFp32_;
236	
237	    GlobalTensor<half> xGmFp16_;
238	    GlobalTensor<half> gammaGmFp16_;
239	    GlobalTensor<half> betaGmFp16_;
240	    GlobalTensor<half> yGmFp16_;
241	
242	    int32_t N_, C_, H_, W_;
243	    int32_t numGroups_, channelsPerGroup_, spatialSize_;
244	    int32_t totalGroups_, usedCoreNum_, tasksPerCore_;
245	    int32_t activateSilu_;
246	    float eps_;
247	    int32_t dtypeSize_;
248	};
249	
250	extern "C" __global__ __aicore__ void group_norm_silu(
251	    GM_ADDR x, GM_ADDR gamma, GM_ADDR beta, GM_ADDR y,
252	    int32_t N, int32_t C, int32_t H, int32_t W,
253	    int32_t numGroups, int32_t channelsPerGroup, int32_t spatialSize,
254	    int32_t totalGroups, int32_t usedCoreNum, int32_t tasksPerCore,
255	    int32_t activateSilu, float eps, int32_t dtypeSize) {
256	
257	    KernelGroupNormSilu op;
258	    op.Init(x, gamma, beta, y, N, C, H, W, numGroups, channelsPerGroup, spatialSize,
259	            totalGroups, usedCoreNum, tasksPerCore, activateSilu, eps, dtypeSize);
260	    op.Process();
261	}
